<?php
session_start();
require_once __DIR__ . '/../includes/auth.php';
require_once __DIR__ . '/../includes/audit.php';
requireRole('admin');

$hospitals = $pdo->query('SELECT id, hospital_name FROM hospitals ORDER BY hospital_name')->fetchAll(PDO::FETCH_ASSOC);
$departments = $pdo->query('SELECT d.id, d.department_name, d.hospital_id, h.hospital_name FROM departments d JOIN hospitals h ON h.id = d.hospital_id ORDER BY h.hospital_name, d.department_name')->fetchAll(PDO::FETCH_ASSOC);
if ($_SERVER['REQUEST_METHOD'] === 'POST') {
    $hospitalId = filter_input(INPUT_POST, 'hospital_id', FILTER_VALIDATE_INT);
    $departmentId = filter_input(INPUT_POST, 'department_id', FILTER_VALIDATE_INT);
    $name = trim($_POST['doctor_name'] ?? ''); $username = trim($_POST['username'] ?? ''); $email = trim($_POST['email'] ?? ''); $password = $_POST['password'] ?? '';
    if (!verifyCsrfToken($_POST['csrf_token'] ?? null) || !$hospitalId || !$departmentId || $name === '' || $username === '' || !filter_var($email, FILTER_VALIDATE_EMAIL) || strlen($password) < 8) { flash('danger', 'Complete all fields; password must be at least 8 characters.'); }
    else { $departmentCheck = $pdo->prepare('SELECT id FROM departments WHERE id = :department_id AND hospital_id = :hospital_id LIMIT 1'); $departmentCheck->execute([':department_id' => $departmentId, ':hospital_id' => $hospitalId]); if (!$departmentCheck->fetchColumn()) { flash('danger', 'The selected department does not belong to that hospital.'); } else { try { $roleQuery = $pdo->prepare("SELECT id FROM roles WHERE role_name = 'doctor' LIMIT 1"); $roleQuery->execute(); $pdo->beginTransaction(); $userInsert = $pdo->prepare('INSERT INTO users (role_id, hospital_id, username, email, password_hash, status) VALUES (:role_id, :hospital_id, :username, :email, :password_hash, \'active\')'); $userInsert->execute([':role_id' => $roleQuery->fetchColumn(), ':hospital_id' => $hospitalId, ':username' => $username, ':email' => $email, ':password_hash' => password_hash($password, PASSWORD_DEFAULT)]); $doctorUserId = (int) $pdo->lastInsertId(); $doctorInsert = $pdo->prepare('INSERT INTO doctors (user_id, department_id, doctor_name, specialization, license_number) VALUES (:user_id, :department_id, :name, :specialization, :license)'); $doctorInsert->execute([':user_id' => $doctorUserId, ':department_id' => $departmentId, ':name' => $name, ':specialization' => trim($_POST['specialization'] ?? '') ?: null, ':license' => trim($_POST['license_number'] ?? '') ?: null]); $doctorId = (int) $pdo->lastInsertId(); $pdo->commit(); logAudit('DOCTOR_CREATED', 'doctor', $doctorId, 'Doctor account created by administrator.', $doctorUserId, 'doctor'); flash('success', 'Doctor account created.'); redirect('doctors.php'); } catch (PDOException $exception) { if ($pdo->inTransaction()) { $pdo->rollBack(); } flash('danger', 'Could not create doctor. Username or email may already exist.'); } } }
}
$doctorsQuery = $pdo->query('SELECT d.doctor_name, d.specialization, u.username, h.hospital_name, dep.department_name FROM doctors d JOIN users u ON u.id = d.user_id JOIN departments dep ON dep.id = d.department_id JOIN hospitals h ON h.id = dep.hospital_id ORDER BY h.hospital_name, d.doctor_name'); $doctors = $doctorsQuery->fetchAll(PDO::FETCH_ASSOC); $pageTitle = 'Doctors'; require __DIR__ . '/../includes/header.php';
?><div class="d-flex justify-content-between align-items-center mb-4"><div><p class="eyebrow">Administration</p><h1 class="h2">Doctors</h1></div></div><div class="row g-4"><div class="col-lg-5"><div class="setup-card"><h2 class="h5">Create doctor account</h2><?php if (!$hospitals || !$departments): ?><p class="text-muted">Add a hospital and department first.</p><?php else: ?><form method="post"><input type="hidden" name="csrf_token" value="<?= e(csrfToken()) ?>"><label class="form-label">Hospital</label><select class="form-select mb-3" name="hospital_id" required><option value="">Select hospital</option><?php foreach ($hospitals as $hospital): ?><option value="<?= (int) $hospital['id'] ?>"><?= e($hospital['hospital_name']) ?></option><?php endforeach; ?></select><label class="form-label">Department</label><select class="form-select mb-3" name="department_id" required><option value="">Select department</option><?php foreach ($departments as $department): ?><option value="<?= (int) $department['id'] ?>"><?= e($department['department_name'] . ' - ' . $department['hospital_name']) ?></option><?php endforeach; ?></select><label class="form-label">Doctor name</label><input class="form-control mb-3" name="doctor_name" required><label class="form-label">Username</label><input class="form-control mb-3" name="username" required><label class="form-label">Email</label><input class="form-control mb-3" type="email" name="email" required><label class="form-label">Password</label><input class="form-control mb-3" type="password" name="password" minlength="8" required><label class="form-label">Specialization</label><input class="form-control mb-3" name="specialization"><label class="form-label">License number</label><input class="form-control mb-3" name="license_number"><button class="btn btn-primary">Create doctor</button></form><?php endif; ?></div></div><div class="col-lg-7"><div class="card border-0 shadow-sm"><div class="card-body"><h2 class="h5">Medical team</h2><div class="table-responsive"><table class="table"><thead><tr><th>Name</th><th>Hospital</th><th>Department</th><th>Username</th></tr></thead><tbody><?php foreach ($doctors as $doctor): ?><tr><td><?= e($doctor['doctor_name']) ?><br><small class="text-muted"><?= e($doctor['specialization']) ?></small></td><td><?= e($doctor['hospital_name']) ?></td><td><?= e($doctor['department_name']) ?></td><td><?= e($doctor['username']) ?></td></tr><?php endforeach; ?><?php if (!$doctors): ?><tr><td colspan="4" class="text-muted">No doctors added yet.</td></tr><?php endif; ?></tbody></table></div></div></div></div></div><?php require __DIR__ . '/../includes/footer.php'; ?>
